from typing import Dict, List, Optional

from .spot_requests import SpotFleetRequest

class CancelledFleetRequests:
    """Storage for cancelled spot fleet requests that still have running instances"""

    def __init__(self) -> None:
        self.cancelled_requests: Dict[str, SpotFleetRequest] = {}

    def add_request(self, request: SpotFleetRequest) -> None:
        self.cancelled_requests[request.id] = request

    def remove_request(self, request_id: str) -> Optional[SpotFleetRequest]:
        """Returns removed request or None if not found"""
        return self.cancelled_requests.pop(request_id, None)

    def get_request(self, request_id: str) -> Optional[SpotFleetRequest]:
        return self.cancelled_requests.get(request_id)

    def get_all_requests(self) -> List[SpotFleetRequest]:
        return list(self.cancelled_requests.values())

